def calculate_q(x, y, z, k):
    # Q = |x+y-2k| + |y+z-2k| + |z+x-2k|
    return abs(x + y - 2 * k) + abs(y + z - 2 * k) + abs(z + x - 2 * k)

collision_results = {}

for k in range(10):
    q_to_triples = {}

    # Iterate over all 1000 triples (x, y, z)
    for x in range(10):
        for y in range(10):
            for z in range(10):
                Q = calculate_q(x, y, z, k)

                if Q not in q_to_triples:
                    q_to_triples[Q] = []

                q_to_triples[Q].append((x, y, z))

    # Check for collisions for this fixed k
    collisions = {}
    for Q, triples in q_to_triples.items():
        if len(triples) > 1:
            collisions[Q] = triples

    collision_results[k] = collisions

# Print findings in a structured way
print("--- Collision Analysis for Fixed k ---")
for k in range(10):
    if collision_results[k]:
        print(f"\nK = {k}: Collisions found.")
        for Q, triples in collision_results[k].items():
            print(f"  Q = {Q}: Resulting triples: {triples}")
    else:
        print(f"\nK = {k}: No collisions found (all 1000 triples yield unique Q values).")

