from collections import Counter

counts = Counter()
for x in range(10):
    for y in range(10):
        for z in range(10):
            s = x + y + z
            counts[s] += 1

print("Distribution of sums S:")
for s in sorted(counts.keys()):
    print(f"S = {s}: Count = {counts[s]}")

# Find the largest collision class
max_count = 0
max_s = -1
for s, count in counts.items():
    if count > max_count:
        max_count = count
        max_s = s

print(f"\nLargest collision class corresponds to S = {max_s} with Count = {max_count}")
